export function hasExplicitDeletedListing(html){for(const match of String(html||"").matchAll(/<script\b[^>]*\bid=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/gi)){try{const root=JSON.parse(match[1]),stack=[root],seen=new Set;while(stack.length){const value=stack.pop();if(!value||typeof value!=="object"||seen.has(value))continue;seen.add(value);if(value.isDeleted===true)return true;for(const child of Object.values(value))if(child&&typeof child==="object")stack.push(child)}}catch{}}return false}
